'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var hasIteratorSymbolSupport = require( '@stdlib/assert/has-iterator-symbol-support' );
var ITERATOR_SYMBOL = require( '@stdlib/symbol/iterator' );
var namedtypedtuple = require( './../lib' );


// VARIABLES //

var HAS_ITERATOR_SYMBOL = hasIteratorSymbolSupport();


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has a `keys` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasOwnProp( p, 'keys' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.keys ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.keys.call( value );
		};
	}
});

tape( 'the method returns an iterator protocol-compliant object which iterates over tuple keys', function test( t ) {
	var Point;
	var iter;
	var v;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 10, 20, 30 ] );
	iter = p.keys();

	v = iter.next();
	t.strictEqual( v.done, false, 'returns expected value' );
	t.deepEqual( v.value, [ 0, 'x' ], 'returns expected value' );

	v = iter.next();
	t.strictEqual( v.done, false, 'returns expected value' );
	t.deepEqual( v.value, [ 1, 'y' ], 'returns expected value' );

	v = iter.next();
	t.strictEqual( v.done, false, 'returns expected value' );
	t.deepEqual( v.value, [ 2, 'z' ], 'returns expected value' );

	v = iter.next();
	t.strictEqual( v.done, true, 'returns expected value' );
	t.strictEqual( v.value, void 0, 'returns expected value' );

	t.end();
});

tape( 'the returned iterator has a `return` method for closing an iterator (no argument)', function test( t ) {
	var Point;
	var iter;
	var v;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 10, 20, 30 ] );
	iter = p.keys();

	v = iter.next();
	t.strictEqual( v.done, false, 'returns expected value' );

	v = iter.return();
	t.strictEqual( v.value, void 0, 'returns expected value' );
	t.strictEqual( v.done, true, 'returns expected value' );

	v = iter.next();
	t.strictEqual( v.value, void 0, 'returns expected value' );
	t.strictEqual( v.done, true, 'returns expected value' );

	t.end();
});

tape( 'the returned iterator has a `return` method for closing an iterator (argument)', function test( t ) {
	var Point;
	var iter;
	var v;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 10, 20, 30 ] );
	iter = p.keys();

	v = iter.next();
	t.strictEqual( v.done, false, 'returns expected value' );

	v = iter.return( 'finished' );
	t.strictEqual( v.value, 'finished', 'returns expected value' );
	t.strictEqual( v.done, true, 'returns expected value' );

	v = iter.next();
	t.strictEqual( v.value, void 0, 'returns expected value' );
	t.strictEqual( v.done, true, 'returns expected value' );

	t.end();
});

tape( 'if the environment supports `Symbol.iterator`, the returned iterator is iterable', function test( t ) {
	var Point;
	var iter1;
	var iter2;
	var v1;
	var v2;
	var p;

	if ( !HAS_ITERATOR_SYMBOL ) {
		t.pass( 'environment does not support Symbol.iterator' );
		return t.end();
	}
	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 10, 20, 30 ] );
	iter1 = p.keys();

	t.strictEqual( isFunction( iter1[ ITERATOR_SYMBOL ] ), true, 'returns expected value' );

	iter2 = iter1[ ITERATOR_SYMBOL ]();

	v1 = iter1.next();
	v2 = iter2.next();

	t.deepEqual( v1.value, v2.value, 'returns expected value' );

	t.end();
});
